item.aggregated_output:
                revision,
            ]
        )
        resolved = _run_git(
            ["git", "-C", str(bare), "rev-parse", "FETCH_HEAD^{commit}"]
        ).decode("ascii").strip()
        if resolved != revision:
            raise DiscoveryExecutionError(
                "SOURCE_SNAPSHOT_MISSING",
                f"pinned source resolved to an unexpected commit: {resolved}",
            )
        commit_bytes = _run_git(
            ["git", "-C", str(bare), "cat-file", "commit", revision]
        )
        tree_bytes = _run_git(
            ["git", "-C", str(bare), "ls-tree", "-r", "-z", revision]
        )
        commit_descriptor = context.raw_store.put(
            commit_bytes, media_type=GIT_COMMIT_MEDIA_TYPE
        )
        tree_descriptor = context.raw_store.put(
            tree_bytes, media_type=GIT_TREE_MEDIA_TYPE
        )
        entries = parse_git_ls_tree(tree_bytes)
        requested_paths = set(secondary_paths)
        selected = [
            entry
            for entry in entries
            if entry.object_type == "blob"
            and (include_path(entry.path) or entry.path in requested_paths)
        ]
        blobs: dict[str, dict[str, Any]] = {}
        for entry in selected:
            blob = _run_git(
                ["git", "-C", str(bare), "cat-file", "blob", entry.object_sha]
            )
            descriptor = context.raw_store.put(blob, media_type=SOURCE_BLOB_MEDIA_TYPE)
            blobs[entry.path] = {
                "mode": entry.mode,
                "object_type": entry.object_type,
                "object_sha": entry.object_sha,
                "artifact": descriptor,
            }
    return {
        "repository": repository,
        "revision": revision,
        "commit_object": commit_descriptor,
        "tree_listing": tree_descriptor,
        "selected_blob_count": len(blobs),
        "blobs": blobs,
    }


def _last_attempt_record(request: Mapping[str, Any]) -> Mapping[str, Any]:
    attempts = request.get("attempts")
    if not isinstance(attempts, list) or not attempts:
        raise DiscoveryExecutionError("RAW_CAPTURE_INCOMPLETE", "request has no attempts")
    value = attempts[-1]
    if not isinstance(value, Mapping):
        raise DiscoveryExecutionError("RAW_CAPTURE_INCOMPLETE", "attempt is malformed")
    return value


class GitHubEvidence:
    """Deduplicated API capture index with no scientific interpretation."""

    def __init__(self, context: CaptureContext | None = None) -> None:
        self.context = context
        self.entries: list[dict[str, Any]] = []
        self._cache: dict[str, tuple[Any | None, dict[str, Any]]] = {}

    @staticmethod
    def _key(
        *,
        method: str,
        endpoint: str,
        ordered_parameters: Sequence[tuple[str, str]],
        json_body: Mapping[str, Any] | None,
        capture_scope: str | None = None,
    ) -> str:
        key_material: dict[str, Any] = {
            "method": method,
            "endpoint": endpoint,
            "ordered_parameters": [list(item) for item in ordered_parameters],
            "json_body": json_body,
        }
        if capture_scope is not None:
            key_material["capture_scope"] = capture_scope
        return "CMVP-API-03-" + sha256_bytes(
            canonical_document_bytes(key_material)
        )

    def capture(
        self,
        *,
        method: str,
        endpoint: str,
        ordered_parameters: Sequence[tuple[str, str]] = (),
        json_body: Mapping[str, Any] | None = None,
        exact_query: str | None = None,
        partition_path: str | None = None,
        partition_start_utc: str | None = None,
        partition_end_utc: str | None = None,
        page: int | None = None,
        graphql_cursor: str | None = None,
        sort: str | None = None,
        order: str | None = None,
        allow_one_redirect: bool = True,
        capture_scope: str | None = None,
    ) -> tuple[Any | None, dict[str, Any]]:
        if self.context is None:
            raise DiscoveryExecutionError("CAPTURE_CONTEXT_MISSING", endpoint)
        key = self._key(
            method=method,
            endpoint=endpoint,
            ordered_parameters=ordered_parameters,
            json_body=json_body,
            capture_scope=capture_scope,
        )
        cached = self._cache.get(key)
        if cached is not None:
            return cached
        try:
            payload, request = self.context.api.request_json(
                method=method,
                endpoint=endpoint,
                ordered_parameters=ordered_parameters,
                exact_query=exact_query,
                partition_path=partition_path,
                partition_start_utc=partition_start_utc,
                partition_end_utc=partition_end_utc,
                page=page,
                graphql_cursor=graphql_cursor,
                sort=sort,
                order=order,
                json_body=json_body,
                allow_one_redirect=allow_one_redirect,
            )
            last = _last_attempt_record(request)
            entry = {
                "evidence_key": key,
                "request_number": request["request_number"],
                "status": "AVAILABLE",
                "http_status": last["http_status"],
                "raw_artifact": last["body"],
                "request_body": json_body,
            }
            result = (payload, entry)
        except DiscoveryExecutionError as error:
            if error.http_status not in {404, 410}:
                raise
            request = self.context.api.requests[-1]
            last = _last_attempt_record(request)
            entry = {
                "evidence_key": key,
                "request_number": request["request_number"],
                "status": "UNAVAILABLE",
                "http_status": error.http_status,
                "raw_artifact": last["body"],
                "request_body": json_body,
            }
            result = (None, entry)
        if capture_scope is not None:
            entry["capture_scope"] = capture_scope
        self.entries.append(entry)
        self._cache[key] = result
        return result

    def read_payload(
        self, *, root: Path, entry: Mapping[str, Any]
    ) -> Mapping[str, Any] | list[Any] | None:
        if entry.get("status") == "UNAVAILABLE":
            return None
        descriptor = entry.get("raw_artifact")
        if not isinstance(descriptor, Mapping):
            raise DiscoveryExecutionError("RAW_CAPTURE_INCOMPLETE", "missing API body")
        path = root / str(descriptor.get("path"))
        data = path.read_bytes()
        if sha256_bytes(data) != descriptor.get("sha256"):
            raise DiscoveryExecutionError(
                "RAW_ARTIFACT_HASH_MISMATCH", f"API evidence mismatch: {path}"
            )
        try:
            payload = json.loads(data)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise DiscoveryExecutionError("SOURCE_SCHEMA_DRIFT", str(error)) from error
        if not isinstance(payload, (Mapping, list)):
            raise DiscoveryExecutionError("SOURCE_SCHEMA_DRIFT", "API JSON is scalar")
        return payload


def _api_repo_endpoint(owner: str, repository: str) -> str:
    return (
        "https://api.github.com/repos/"
        f"{quote(owner, safe='')}/{quote(repository, safe='')}"
    )


def _repository_coordinates_from_api_url(value: Any) -> tuple[str, str]:
    if not isinstance(value, str):
        raise DiscoveryExecutionError(
            "SOURCE_SCHEMA_DRIFT", "repository_url must be a string"
        )
    match = API_REPOSITORY_PATTERN.fullmatch(value)
    if match is None:
        raise DiscoveryExecutionError(
            "SOURCE_SCHEMA_DRIFT", "repository_url is not canonical GitHub API URL"
        )
    return match.group(1), match.group(2)


def _mapping(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise DiscoveryExecutionError("SOURCE_SCHEMA_DRIFT", f"{label} must be object")
    return value


def _positive_int(value: Any, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise DiscoveryExecutionError(
            "SOURCE_SCHEMA_DRIFT", f"{label} must be positive integer"
        item = payload["items"][index]
    except (IndexError, TypeError) as error:
        raise DiscoveryExecutionError("RAW_CAPTURE_INCOMPLETE", str(error)) from error
    return _mapping(item, "search item")


def _capture_issue_relations(
    evidence: GitHubEvidence,
    *,
    owner: str,
    repository: str,
    number: int,
) -> list[Mapping[str, Any]]:
    cursor: str | None = None
    merged_nodes: list[Mapping[str, Any]] = []
    while True:
        variables = {
            "owner": owner,
            "repository": repository,
            "number": number,
            "cursor": cursor,
        }
        payload, _ = evidence.capture(
            method="POST",
            endpoint="https://api.github.com/graphql",
            json_body={"query": GRAPHQL_DOCUMENT, "variables": variables},
            exact_query=GRAPHQL_DOCUMENT,
            graphql_cursor=cursor,
            allow_one_redirect=False,
        )
        if not isinstance(payload, Mapping):
            return []
        if payload.get("errors"):
            raise DiscoveryExecutionError(
                "SOURCE_SCHEMA_DRIFT", "GraphQL response contains errors"
            )
        data = payload.get("data")
        repository_node = data.get("repository") if isinstance(data, Mapping) else None
        issue = (
            repository_node.get("issue")
            if isinstance(repository_node, Mapping)
            else None
        )
        connection = (
            issue.get("closedByPullRequestsReferences")
            if isinstance(issue, Mapping)
            else None
        )
        if not isinstance(connection, Mapping):
            return []
        nodes = connection.get("nodes")
        page_info = connection.get("pageInfo")
        if not isinstance(nodes, list) or not isinstance(page_info, Mapping):
            return []
        if any(not isinstance(node, Mapping) for node in nodes):
            return []
        merged_nodes.extend(node for node in nodes if node.get("merged") is True)
        has_next = page_info.get("hasNextPage")
        end_cursor = page_info.get("endCursor")
        if has_next is False:
            break
        if has_next is not True or not isinstance(end_cursor, str) or not end_cursor:
            return []
        cursor = end_cursor
    return merged_nodes


def capture_searches(
    context: CaptureContext,
    evidence: GitHubEvidence,
    *,
    search_spec: Mapping[str, Any],
) -> None:
    """Capture all eight queries atomically, then their immutable PR evidence."""

    queries = search_spec.get("queries")
    if not isinstance(queries, list) or len(queries) != 8:
        raise DiscoveryExecutionError(
            "SOURCE_SCHEMA_DRIFT", "frozen search specification must have eight queries"
        )
    item_refs: list[dict[str, Any]] = []
    query_by_id: dict[str, Mapping[str, Any]] = {}
    for query in queries:
        query_value = _mapping(query, "query specification")
        query_id = query_value.get("query_id")
        root_query = query_value.get("query")
        if not isinstance(query_id, str) or not isinstance(root_query, str):
            raise DiscoveryExecutionError("SOURCE_SCHEMA_DRIFT", "query is malformed")
        query_by_id[query_id] = query_value
        item_refs.extend(
            _capture_query_partitions_v04(
                context,
                evidence,
                query_id=query_id,
                root_query=root_query,
            )
        )
    observed_identities, cross_leaf_diagnostics = _group_observed_search_items(
        item_refs
    )
    search_capture = context.source_capture.get(SEARCH_CAPTURE_KEY_V04)
    if not isinstance(search_capture, dict) or not isinstance(
        search_capture.get("diagnostics"), dict
    ):
        raise DiscoveryExecutionError(
            "EXECUTION_CONFIGURATION_INVALID", "Search observation index is missing"
        )
    search_capture["diagnostics"]["cross_leaf_duplicates"] = (
        cross_leaf_diagnostics
    )
    _finalize_search_observation_summary(
        context=context,
        observed_identities=observed_identities,
        returned_occurrence_count=len(item_refs),
    )
    for observed_identity in observed_identities:
        item_ref = _mapping(
            observed_identity.get("primary_occurrence"),
            "primary Search observation",
        )
        query = query_by_id[str(item_ref["query_id"])]
        observed_query_ids = observed_identity.get("observed_query_ids")
        if not isinstance(observed_query_ids, list) or not observed_query_ids:
            raise DiscoveryExecutionError(
                "SOURCE_IDENTITY_FIELD_MISSING",
                "Search source identity has no query provenance",
            )
        observed_object_types = {
            query_by_id[str(observed_query_id)].get("object_type")
            for observed_query_id in observed_query_ids
        }
        if len(observed_object_types) != 1:
            raise DiscoveryExecutionError(
                "SOURCE_IDENTITY_CONFLICT",
                "one Search node ID was observed under conflicting object types",
            )
        item = _item_from_capture(context, evidence, item_ref)
        native = {
            "api_version": API_VERSION,
            "github_search_node_id": item_ref["node_id"],
        }
        context.add_source_object(
            {
                "source_object_id": f"GITHUB_SEARCH:{item_ref['node_id']}",
                "source_native_identity": native,
                **item_ref,
                "observed_query_ids": observed_query_ids,
                "observed_leaf_provenance": observed_identity[
                    "observed_leaf_provenance"
                ],
            }
        )
        try:
            owner, repository = _repository_coordinates_from_api_url(
                item.get("repository_url")
            )
            number = _positive_int(item.get("number"), "search item number")
        except DiscoveryExecutionError:
            continue
        if query.get("object_type") == "PULL_REQUEST":
            repository_payload, _ = _capture_repository(evidence, owner, repository)
            if repository_payload is None:
                continue
            try:
                normalized = _normalized_repository_payload(repository_payload)
            except SourceRecordRejected:
                continue
            _capture_pull_request(
                evidence,
                str(normalized["owner"]),
                str(normalized["name"]),
                number,
            )
        elif query.get("object_type") == "ISSUE":
            nodes = _capture_issue_relations(
                evidence,
                owner=owner,
                repository=repository,
                number=number,
            )
            repository_payload, _ = _capture_repository(evidence, owner, repository)
            if repository_payload is None:
                continue
            for node in nodes:
                repository_node = node.get("repository")
                name_with_owner = (
                    repository_node.get("nameWithOwner")
                    if isinstance(repository_node, Mapping)
                    else None
                )
                pr_number = node.get("number")
                if (
                    isinstance(name_with_owner, str)
                    and name_with_owner.count("/") == 1
                    and isinstance(pr_number, int)
                    and not isinstance(pr_number, bool)
                    and pr_number > 0
                ):
                    pr_owner, pr_repository = name_with_owner.split("/", 1)
                    _capture_repository(evidence, pr_owner, pr_repository)
                    _capture_pull_request(
                        evidence, pr_owner, pr_repository, pr_number
                    )
        else:
            raise DiscoveryExecutionError(
                "SOURCE_SCHEMA_DRIFT", "query object_type is invalid"
            )


def load_verified_capture(
    source_root: Path,
) -> tuple[dict[str, Any], str, dict[str, Any]]:
    """Rehash a complete capture and return its raw capture index."""

    manifest_path = source_root / "capture-manifest.json"
    sidecar_path = source_root / "capture-manifest.json.sha256"
    manifest_bytes = manifest_path.read_bytes()
    digest = sha256_bytes(manifest_bytes)
    if sidecar_path.read_text(encoding="ascii").strip() != digest:
        raise DiscoveryExecutionError(
            "RAW_ARTIFACT_HASH_MISMATCH", f"capture sidecar mismatch: {source_root}"
        try:
            payload = json.loads(_read_artifact(self.source_root, descriptor))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise DiscoveryExecutionError("SOURCE_SCHEMA_DRIFT", str(error)) from error
        if not isinstance(payload, (Mapping, list)):
            raise DiscoveryExecutionError("SOURCE_SCHEMA_DRIFT", "API payload is scalar")
        return payload


def _unique_artifacts(values: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    by_digest: dict[str, dict[str, Any]] = {}
    for value in values:
        digest = value.get("sha256")
        if isinstance(digest, str):
            by_digest[digest] = dict(value)
    return [by_digest[digest] for digest in sorted(by_digest)]


def _captured_repository(
    captured: CapturedGitHubEvidence,
    *,
    owner: str,
    repository: str,
    artifacts: list[dict[str, Any]],
    expected_id: int | None = None,
) -> dict[str, Any]:
    payload = captured.get(
        method="GET",
        endpoint=_api_repo_endpoint(owner, repository),
        artifacts=artifacts,
    )
    if payload is None:
        raise SourceRecordRejected(
            "GITHUB_REPOSITORY_UNAVAILABLE", "repository returned 404 or 410"
        )
    if not isinstance(payload, Mapping):
        raise SourceRecordRejected(
            "SOURCE_SCHEMA_DRIFT", "repository detail is not an object"
        )
    normalized = _normalized_repository_payload(payload)
    if expected_id is not None and normalized["id"] != expected_id:
        raise SourceRecordRejected(
            "GITHUB_REPOSITORY_IDENTITY_CHANGED",
            "repository redirect or detail changed numeric identity",
        )
    return normalized


def _captured_commit(
    captured: CapturedGitHubEvidence,
    *,
    owner: str,
    repository: str,
    commit_sha: str,
    artifacts: list[dict[str, Any]],
) -> Mapping[str, Any]:
    root = _api_repo_endpoint(owner, repository)
    payload = captured.get(
        method="GET",
        endpoint=f"{root}/git/commits/{commit_sha}",
        artifacts=artifacts,
    )
    if payload is None:
        raise SourceRecordRejected(
            "GITHUB_COMMIT_UNAVAILABLE", f"commit {commit_sha} is unavailable"
        )
    if not isinstance(payload, Mapping) or payload.get("sha") != commit_sha:
        raise SourceRecordRejected(
            "SOURCE_SCHEMA_DRIFT", "commit response does not match exact SHA"
        )
    tree = payload.get("tree")
    tree_sha = tree.get("sha") if isinstance(tree, Mapping) else None
    if not isinstance(tree_sha, str) or SHA1_PATTERN.fullmatch(tree_sha) is None:
        raise SourceRecordRejected("SOURCE_SCHEMA_DRIFT", "commit tree is missing")
    tree_payload = captured.get(
        method="GET",
        endpoint=f"{root}/git/trees/{tree_sha}",
        artifacts=artifacts,
    )
    if (
        not isinstance(tree_payload, Mapping)
        or tree_payload.get("sha") != tree_sha
        or not isinstance(tree_payload.get("tree"), list)
    ):
        raise SourceRecordRejected("SOURCE_SCHEMA_DRIFT", "tree response is malformed")
    return payload


def _parent_shas(commit: Mapping[str, Any]) -> list[str]:
    parents = commit.get("parents")
    if not isinstance(parents, list):
        raise SourceRecordRejected("SOURCE_SCHEMA_DRIFT", "commit parents missing")
    values: list[str] = []
    for index, parent in enumerate(parents):
        if not isinstance(parent, Mapping):
            raise SourceRecordRejected("SOURCE_SCHEMA_DRIFT", "commit parent malformed")
        value = parent.get("sha")
        if not isinstance(value, str) or SHA1_PATTERN.fullmatch(value) is None:
            raise SourceRecordRejected(
                "SOURCE_SCHEMA_DRIFT", f"commit parent {index} is malformed"
            )
        values.append(value)
    return values


def _captured_pr_episode(
    captured: CapturedGitHubEvidence,
    *,
    owner: str,
    repository: str,
    number: int,
    artifacts: list[dict[str, Any]],
    expected_repository_id: int | None = None,
) -> tuple[Any, dict[str, Any], Mapping[str, Any]]:
    repository_value = _captured_repository(
        captured,
        owner=owner,
        repository=repository,
        artifacts=artifacts,
        expected_id=expected_repository_id,
    )
    final_owner = str(repository_value["owner"])
    final_repository = str(repository_value["name"])
    evidence_owner = final_owner
    evidence_repository = final_repository
    root = _api_repo_endpoint(final_owner, final_repository)
    requested_root = _api_repo_endpoint(owner, repository)
    if (
        owner.casefold() == final_owner.casefold()
        and repository.casefold() == final_repository.casefold()
        and requested_root != root
    ):
        final_key = GitHubEvidence._key(
            method="GET",
            endpoint=f"{root}/pulls/{number}",
            ordered_parameters=(),
            json_body=None,
        )
        requested_key = GitHubEvidence._key(
            method="GET",
            endpoint=f"{requested_root}/pulls/{number}",
            ordered_parameters=(),
            json_body=None,
        )
        if final_key not in captured.entries and requested_key in captured.entries:
            evidence_owner = owner
            evidence_repository = repository
            root = requested_root
    payload = captured.get(
        method="GET", endpoint=f"{root}/pulls/{number}", artifacts=artifacts
    )
    if payload is None:
        raise SourceRecordRejected(
            "GITHUB_ISSUE_OR_PR_UNAVAILABLE", "pull request is unavailable"
        )
    if not isinstance(payload, Mapping):
        raise SourceRecordRejected(
            "GITHUB_PR_DETAIL_INCOMPLETE", "pull request detail is not object"
        )
    if payload.get("number") != number:
        raise SourceRecordRejected(
            "GITHUB_PR_DETAIL_INCOMPLETE", "pull request number mismatch"
        )
    if payload.get("merged") is not True or not isinstance(
        payload.get("merged_at"), str
    ):
        raise SourceRecordRejected("GITHUB_PR_NOT_MERGED", "pull request is not merged")
    commit_count = payload.get("commits")
    if (
        isinstance(commit_count, bool)
        or not isinstance(commit_count, int)
        or commit_count <= 0
    ):
        raise SourceRecordRejected(
            "GITHUB_PR_DETAIL_INCOMPLETE", "positive PR commit count is required"
        )
    captured_commit_shas: list[str] = []
    for page in range(1, math.ceil(commit_count / 100) + 1):
        commits_payload = captured.get(
            method="GET",
            endpoint=f"{root}/pulls/{number}/commits",
            ordered_parameters=(("per_page", "100"), ("page", str(page))),
            artifacts=artifacts,
        )
        if not isinstance(commits_payload, list):
            raise SourceRecordRejected(
                "GITHUB_PR_DETAIL_INCOMPLETE", "PR commit page is unavailable"
            )
        for commit in commits_payload:
            if not isinstance(commit, Mapping):
                raise SourceRecordRejected(
                    "GITHUB_PR_DETAIL_INCOMPLETE", "PR commit entry malformed"
                )
            captured_commit_shas.append(
                _record_sha(commit.get("sha"), "PR commit SHA")
            )
    if len(captured_commit_shas) != commit_count:
        raise SourceRecordRejected(
            "GITHUB_PR_DETAIL_INCOMPLETE", "complete PR commit list count mismatch"
        )
    head = payload.get("head")
    base = payload.get("base")
    if not isinstance(head, Mapping) or not isinstance(base, Mapping):
        raise SourceRecordRejected(
            "GITHUB_PR_DETAIL_INCOMPLETE", "PR base/head objects are missing"
        )
    head_sha = _record_sha(head.get("sha"), "PR head SHA")
    base_sha = _record_sha(base.get("sha"), "PR base SHA")
    merge_sha = _record_sha(payload.get("merge_commit_sha"), "PR merge commit SHA")
    endpoint_commit = _captured_commit(
        captured,
        owner=evidence_owner,
        repository=evidence_repository,
        commit_sha=merge_sha,
        artifacts=artifacts,
    )
    try:
        episode = resolve_merged_pr_episode(
            repository_id=repository_value["id"],
            merged=True,
            merged_at_utc=str(payload["merged_at"]),
            head_sha=head_sha,
            repair_endpoint_sha=merge_sha,
            endpoint_parent_shas=_parent_shas(endpoint_commit),
            pr_commit_count=commit_count,
        )
    except CandidateSourceV03Error as error:
        raise SourceRecordRejected(error.code, str(error)) from error
    _captured_commit(
        captured,
        owner=evidence_owner,
        repository=evidence_repository,
        commit_sha=episode.candidate_snapshot_commit_sha,
        artifacts=artifacts,
    )
    return episode, repository_value, {
        "number": number,
        "base_sha": base_sha,
        "head_sha": head_sha,
        "merge_commit_sha": merge_sha,
        "merged_at": payload["merged_at"],
        "commit_shas": captured_commit_shas,
    }


